package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
)

func main() {
	url := "http://example.com/api/endpoint"

	// Create a URL struct from the string URL.
	req, err := http.NewRequest("POST", url, nil)
	if err != nil {
		fmt.Println("The request could not be created:", err)
		return
	}

	// Write some data to send with the POST message.
	jsonData := map[string]interface{}{
		"name": "John Doe",
		"age":  "30",
	}
	data, _ := json.Marshal(jsonData)

	if err := req.Write(data); err != nil {
		fmt.Println("The request could not be sent:", err)
		return
	}

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		fmt.Println("The response could not be created: ", err)
	} else {
		defer resp.Body.Close()

		body, _ := ioutil.ReadAll(resp.Body)

		fmt.Printf("Response:\n%s", string(body))
	}
}
```

### Explanation:
1. **URL Creation**: The `url` variable holds the URL of the endpoint you want to send a POST request to.
2. **Creating the Request**: 
   - A new HTTP request is created using `http.NewRequest`.
3. **Adding Data**:
   - `req.Write(data)` sends the data as part of the body of the POST request.

### Example Use Case:

If your endpoint expects JSON and you want to send a user's details, this snippet will work perfectly for that.

- The JSON data is created using `map[string]interface{}` which can be marshalled into JSON.
- Data is then written into the request body using `req.Write`.

### Important Notes:
- Ensure you handle your HTTP requests correctly. This example assumes basic handling but in a production environment, consider using proper error checking and response parsing.
- For more complex scenarios or additional headers, consider setting up an initial context (`context.Background()`), or even use a client like `http.Client` for managing connections.

You can modify the code to suit your specific requirements, such as adding authentication tokens, cookies, etc.

