7. **Implement Stack Methods:**

Here's a simple implementation of a stack using an array:

```cpp
#include <iostream>
using namespace std;

class Stack {
public:
    int data[10]; // Array to hold stack elements
    int size = 10; // Size of the stack
    int top = -1; // Index for tracking the current position

    void push(int element) {
        if (top == size - 1) {
            cout << "Stack is full.\n";
            return;
        }
        data[++top] = element;
    }

    int pop() {
        if (isEmpty()) {
            cout << "Stack is empty.\n";
            return INT_MIN; // Return a value that indicates an error
        }
        top--;
        return data[top + 1];
    }

    int peek() {
        if (isEmpty()) {
            cout << "Stack is empty.\n";
            return INT_MIN; // Return a value that indicates an error
        }
        return data[top]; 
    }

    bool isEmpty() const {
        return top == -1;
    }
};

int main() {
    Stack s;

    for(int i = 0; i < 5; ++i) { // Push some elements to the stack
        int item;
        cin >> item;
        s.push(item);
    }

    cout << "Top element is: " << s.peek() << endl; // Check peeked value

    for(int i = 4; i >= 0; --i) { // Pop the stack till it's empty
        if (!s.isEmpty()) {
            int item = s.pop();
            cout << item << endl;
        } else {
            break;
        }
    }

    return 0;
}
```

### Explanation:
- **Array Initialization:** The `data` array is initialized with a size of 10, which means the stack can hold up to 9 items.
- **Top Index Management:** The `top` variable keeps track of the current position in the array. It starts at -1 because indexing usually begins from zero.
- **Push Operation (push(int element)):** This method adds an element to the top of the stack by incrementing the index and assigning the new value.
- **Pop Operation (int pop()):** If the stack is not empty, this method returns the current top element; it then decrements `top` and discards the previous value at that location.
- **Peek Operation (int peek()):** Similar to pop but without actually removing an item from the array. It simply returns the element at the current `top`.
- **IsEmpty Method:** This method checks if the stack is empty by verifying whether `top` equals -1.

This implementation allows you to create a basic stack and perform common operations like push, pop, peek, and check emptiness.

