🤖 [Qwen Edge] Certainly! Below is an example of how to implement a singly-linked list in C++. This includes the necessary header files, class definition, and main function that demonstrates usage.

```cpp
#include <iostream>
using namespace std;

// Define a node structure for the linked list
struct Node {
    int data;
    struct Node* next;  // Pointer to the next node

    Node(int val) : data(val), next(nullptr) {}
};

class LinkedList {
private:
    Node *head;  // Pointer to the head of the list

public:
    // Constructor initializes the linked list
    LinkedList() : head(nullptr) {}

    void append(int value);
    void printList();
    ~LinkedList();  // Destructor for clean-up
};

void LinkedList::append(int value) {
    Node* newNode = new Node(value);  // Create a new node with the given value

    if (head == nullptr) {  // If the list is empty, make the new node the head
        head = newNode;
    } else {
        Node *current = head;  // Start from the head of the list

        while (current->next != nullptr) {
            current = current->next;  // Traverse to the end of the list
        }

        current->next = newNode;  // Link the new node to the last one in the list
    }
}

void LinkedList::printList() {
    Node* current = head;

    while (current != nullptr) {  // Traverse the linked list and print each node's data
        cout << current->data << " ";
        current = current->next;
    }

    cout << endl;  // Move to a new line after printing all elements
}

LinkedList::~LinkedList() {
    Node* temp;  // Pointer for temporary node

    while (head != nullptr) {  // Traverse the list and delete each element
        temp = head;  // Save the next node in case of deletion
        head = head->next;  // Move to the next node
        delete temp;  // Delete the current node
    }
}

int main() {
    LinkedList myList;

    myList.append(1);
    myList.append(2);
    myList.append(3);

    cout << "Linked List: ";
    myList.printList();

    return 0;
}
```

### Explanation:

- **Node Structure**: 
  - Each node holds an integer value (`data`) and a pointer to the next node in the list.

- **LinkedList Class**:
  - Contains a `head` pointer that points to the first node of the list.
  - Methods:
    - `append(int value)`: Adds a new node with the specified value at the end of the list.
    - `printList()`: Prints all elements in the linked list.

- **Destructor (`~LinkedList()`)**: 
  - Ensures all dynamically allocated memory is freed when the object goes out of scope, preventing memory leaks.

### Usage:
- The `main` function creates an instance of `LinkedList`, appends three integers to it, and then prints the entire list.

This is a basic implementation that you can expand upon for more complex linked lists with additional features like removing nodes or searching.

