🤖 [Qwen Edge] Certainly! Below is an example of how to implement a doubly linked list using C++. The code includes classes for `Node` and `DoublyLinkedList`, along with methods to add nodes, get elements, remove nodes, and iterate through the list.

```cpp
#include <iostream>

class Node {
public:
    int data;
    Node* next;
    Node* prev;

    Node(int value) : data(value), next(nullptr), prev(nullptr) {}
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;

public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    void addNode(int value) {
        Node* newNode = new Node(value);

        if (head == nullptr && tail == nullptr) {  // Empty list
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    }

    void addNodeAt(int index, int value) {
        if (index < 0 || index > size()) return;

        Node* newNode = new Node(value);

        if (index == 0) {  // Add at the beginning
            newNode->next = head;
            head->prev = newNode;
            head = newNode;
        } else if (head != nullptr && index >= 1) {
            Node* current = head;

            for (int i = 0; i < index - 1; ++i) {
                current = current->next;
            }

            newNode->next = current->next;
            newNode->prev = current;

            if (current->next != nullptr) {  // If it's not the last element
                current->next->prev = newNode;
            }

            current->next = newNode;
        }
    }

    void removeNode(int value) {
        Node* currentNode = head;
        while (currentNode != nullptr && currentNode->data != value) {
            currentNode = currentNode->next;
        }

        if (currentNode == nullptr) return;

        // Remove the node
        if (currentNode->prev != nullptr) {  // It's not at the beginning
            currentNode->prev->next = currentNode->next;
        } else {  // At the beginning
            head = currentNode->next;
        }

        if (currentNode->next != nullptr) {  // Not the last element
            currentNode->next->prev = currentNode->prev;
        } else {  // It's at the end
            tail = currentNode->prev;
        }

        delete currentNode;  // Free memory
    }

    int size() const {
        Node* current = head;
        int count = 0;

        while (current != nullptr) {
            ++count;
            current = current->next;
        }

        return count;
    }
};

int main() {
    DoublyLinkedList list;

    list.addNode(1);
    list.addNode(2);
    list.addNode(3);

    std::cout << "Size of the list: " << list.size() << std::endl;  // Output: 3

    list.removeNode(2);  // Remove element with value 2
    std::cout << "After removal, size: " << list.size() << std::endl;  // Output: 2

    return 0;
}
```

### Explanation:
- **Node Class**: Represents each node in the doubly linked list. Each node contains a `data` field and pointers to the next (`next`) and previous (`prev`) nodes.

- **DoublyLinkedList Class**:
  - The constructor initializes both the head (`head`) and tail (`tail`) of the list as null.
  - Methods for adding elements at specific positions (at the beginning, or any given index) using `addNodeAt`.
  - A method to remove a node by its value using `removeNode`.

### Usage:
- To add nodes: Use `list.addNode(data)` to add an element before the current tail. If you want to add it after an existing position, use `list.addNodeAt(index, data)`.
- To list size: Call `size()` which returns the number of elements in the list.
- Remove a node by value using `removeNode(value)`.

### Example Output:
```
Size of the list: 3
After removal, size: 2
```

This implementation provides a basic structure for managing and manipulating doubly linked lists with C++.

